  @Test
  void roundTripsColumnIndexes() {
    PrimitiveType type = Types.required(PrimitiveTypeName.INT32).named("id");
    ByteBuffer min = ByteBuffer.wrap(BytesUtils.intToBytes(10));
    ByteBuffer max = ByteBuffer.wrap(BytesUtils.intToBytes(20));
    org.apache.parquet.internal.column.columnindex.ColumnIndex columnIndex =
        org.apache.parquet.internal.column.columnindex.ColumnIndexBuilder.build(
            type,
            org.apache.parquet.internal.column.columnindex.BoundaryOrder.ASCENDING,
            Collections.singletonList(false),
            Collections.singletonList(2L),
            Collections.singletonList(1L),
            Collections.singletonList(min),
            Collections.singletonList(max),
            Arrays.asList(1L, 2L),
            Arrays.asList(0L, 3L));

    ColumnIndex parquetColumnIndex = ParquetMetadataConverter.toParquetColumnIndex(type, columnIndex);
    assertThat(parquetColumnIndex).isNotNull();
    assertThat(parquetColumnIndex.getNull_pages()).containsExactly(false);
    assertThat(parquetColumnIndex.getNull_counts()).containsExactly(2L);
    assertThat(parquetColumnIndex.getNan_counts()).containsExactly(1L);
    assertThat(parquetColumnIndex.getMin_values()).containsExactly(min);
    assertThat(parquetColumnIndex.getMax_values()).containsExactly(max);
    assertThat(parquetColumnIndex.getBoundary_order())
        .isEqualTo(org.apache.parquet.format.BoundaryOrder.ASCENDING);
    assertThat(parquetColumnIndex.getRepetition_level_histograms()).containsExactly(1L, 2L);
    assertThat(parquetColumnIndex.getDefinition_level_histograms()).containsExactly(0L, 3L);

    org.apache.parquet.internal.column.columnindex.ColumnIndex restored =
        ParquetMetadataConverter.fromParquetColumnIndex(type, parquetColumnIndex);
    assertThat(restored.getNullPages()).containsExactly(false);
    assertThat(restored.getNullCounts()).containsExactly(2L);
    assertThat(restored.getNanCounts()).containsExactly(1L);
    assertThat(restored.getMinValues()).containsExactly(min);
    assertThat(restored.getMaxValues()).containsExactly(max);
    assertThat(restored.getBoundaryOrder())
        .isEqualTo(org.apache.parquet.internal.column.columnindex.BoundaryOrder.ASCENDING);
    assertThat(restored.getRepetitionLevelHistogram()).containsExactly(1L, 2L);
    assertThat(restored.getDefinitionLevelHistogram()).containsExactly(0L, 3L);

    assertThat(ParquetMetadataConverter.toParquetColumnIndex(type, null)).isNull();
  }

  @Test
  void skipsColumnIndexesForTypesWithUndefinedColumnOrder() {
    PrimitiveType type = Types.required(PrimitiveTypeName.INT96).named("legacy");
    ByteBuffer value = ByteBuffer.wrap(new byte[12]);
    org.apache.parquet.internal.column.columnindex.ColumnIndex index =
        org.apache.parquet.internal.column.columnindex.ColumnIndexBuilder.build(
            type,
            org.apache.parquet.internal.column.columnindex.BoundaryOrder.UNORDERED,
            Collections.singletonList(false),
            Collections.singletonList(0L),
            Collections.singletonList(value),
            Collections.singletonList(value));
    ColumnIndex formatIndex = new ColumnIndex(
        Collections.singletonList(false),
        Collections.singletonList(value),
        Collections.singletonList(value),
        org.apache.parquet.format.BoundaryOrder.UNORDERED);
    formatIndex.setNull_counts(Collections.singletonList(0L));

    assertThat(ParquetMetadataConverter.toParquetColumnIndex(type, index)).isNull();
    assertThat(ParquetMetadataConverter.fromParquetColumnIndex(type, formatIndex)).isNull();
  }

  @Test
  void roundTripsOffsetIndexesAndOptionalUnencodedByteCounts() {
    org.apache.parquet.internal.column.columnindex.OffsetIndex index =
        org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder.getBuilder()
            .add(100L, 50, 0L, Optional.of(11L))
            .add(200L, 60, 10L, Optional.of(22L))
            .build();

    OffsetIndex parquetIndex = ParquetMetadataConverter.toParquetOffsetIndex(index);
    assertThat(parquetIndex.getPage_locations())
        .extracting(PageLocation::getOffset, PageLocation::getCompressed_page_size, PageLocation::getFirst_row_index)
        .containsExactly(
            org.assertj.core.groups.Tuple.tuple(100L, 50, 0L),
            org.assertj.core.groups.Tuple.tuple(200L, 60, 10L));
    assertThat(parquetIndex.getUnencoded_byte_array_data_bytes()).containsExactly(11L, 22L);

    org.apache.parquet.internal.column.columnindex.OffsetIndex restored =
        ParquetMetadataConverter.fromParquetOffsetIndex(parquetIndex);
    assertThat(restored.getPageCount()).isEqualTo(2);
    assertThat(restored.getOffset(0)).isEqualTo(100L);
    assertThat(restored.getCompressedPageSize(0)).isEqualTo(50);
    assertThat(restored.getFirstRowIndex(0)).isZero();
    assertThat(restored.getUnencodedByteArrayDataBytes(0)).contains(11L);
    assertThat(restored.getOffset(1)).isEqualTo(200L);
    assertThat(restored.getUnencodedByteArrayDataBytes(1)).contains(22L);

    org.apache.parquet.internal.column.columnindex.OffsetIndex noUnencoded =
        org.apache.parquet.internal.column.columnindex.OffsetIndexBuilder.getBuilder()
            .add(300L, 70, 20L)
            .build();
    OffsetIndex parquetNoUnencoded = ParquetMetadataConverter.toParquetOffsetIndex(noUnencoded);
    assertThat(parquetNoUnencoded.isSetUnencoded_byte_array_data_bytes()).isFalse();
    org.apache.parquet.internal.column.columnindex.OffsetIndex restoredNoUnencoded =
        ParquetMetadataConverter.fromParquetOffsetIndex(parquetNoUnencoded);
    assertThat(restoredNoUnencoded.getUnencodedByteArrayDataBytes(0)).isEmpty();
  }

  @Test
  void buildsBloomFilterHeadersAndRejectsUnsupportedFilters() {
    BlockSplitBloomFilter bloomFilter = new BlockSplitBloomFilter(64);
    org.apache.parquet.format.BloomFilterHeader header =
        ParquetMetadataConverter.toBloomFilterHeader(bloomFilter);
    assertThat(header.getNumBytes()).isEqualTo(bloomFilter.getBitsetSize());
    assertThat(header.getAlgorithm().getSetField())
        .isEqualTo(org.apache.parquet.format.BloomFilterAlgorithm._Fields.BLOCK);
    assertThat(header.getHash().getSetField())
        .isEqualTo(org.apache.parquet.format.BloomFilterHash._Fields.XXHASH);
    assertThat(header.getCompression().getSetField())
        .isEqualTo(org.apache.parquet.format.BloomFilterCompression._Fields.UNCOMPRESSED);

    BloomFilter unsupported = new BlockSplitBloomFilter(64) {
      @Override
      public Algorithm getAlgorithm() {
        return null;
      }
    };
    assertThatThrownBy(() -> ParquetMetadataConverter.toBloomFilterHeader(unsupported))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("Failed to build thrift structure for BloomFilterHeader");
  }

  @Test
  void roundTripsSizeStatistics() {
    PrimitiveType type = Types.required(PrimitiveTypeName.BINARY).named("data");
    SizeStatistics stats = new SizeStatistics(
        type,
        99L,
        Arrays.asList(5L, 6L),
        Arrays.asList(1L, 2L, 3L));

    org.apache.parquet.format.SizeStatistics formatStats =
        ParquetMetadataConverter.toParquetSizeStatistics(stats);
    assertThat(formatStats.getUnencoded_byte_array_data_bytes()).isEqualTo(99L);
    assertThat(formatStats.getRepetition_level_histogram()).containsExactly(5L, 6L);
    assertThat(formatStats.getDefinition_level_histogram()).containsExactly(1L, 2L, 3L);

    SizeStatistics restored = ParquetMetadataConverter.fromParquetSizeStatistics(formatStats, type);
    assertThat(restored.getType()).isEqualTo(type);
    assertThat(restored.getUnencodedByteArrayDataBytes()).contains(99L);
    assertThat(restored.getRepetitionLevelHistogram()).containsExactly(5L, 6L);
    assertThat(restored.getDefinitionLevelHistogram()).containsExactly(1L, 2L, 3L);

    assertThat(ParquetMetadataConverter.toParquetSizeStatistics(null)).isNull();
    assertThat(ParquetMetadataConverter.fromParquetSizeStatistics(null, type)).isNull();
  }

  @Test
  void convertsGeospatialStatisticsAndSortsTypeCodes() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    org.apache.parquet.column.statistics.geospatial.BoundingBox boundingBox =
        new org.apache.parquet.column.statistics.geospatial.BoundingBox(
            -10, 10, -20, 20, -5, 5, Double.NaN, Double.NaN);
    org.apache.parquet.column.statistics.geospatial.GeospatialTypes geospatialTypes =
        new org.apache.parquet.column.statistics.geospatial.GeospatialTypes(
            new HashSet<>(Arrays.asList(5001, 1001)));
    org.apache.parquet.column.statistics.geospatial.GeospatialStatistics stats =
        new org.apache.parquet.column.statistics.geospatial.GeospatialStatistics(
            boundingBox, geospatialTypes);

    org.apache.parquet.format.GeospatialStatistics formatStats =
        converter.toParquetGeospatialStatistics(stats);
    assertThat(formatStats.getBbox().getXmin()).isEqualTo(-10);
    assertThat(formatStats.getBbox().getXmax()).isEqualTo(10);
    assertThat(formatStats.getBbox().getYmin()).isEqualTo(-20);
    assertThat(formatStats.getBbox().getYmax()).isEqualTo(20);
    assertThat(formatStats.getBbox().getZmin()).isEqualTo(-5);
    assertThat(formatStats.getBbox().getZmax()).isEqualTo(5);
    assertThat(formatStats.getBbox().isSetMmin()).isFalse();
    assertThat(formatStats.getGeospatial_types()).containsExactly(1001, 5001);

    PrimitiveType type = Types.optional(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.geometryType("OGC:CRS84"))
        .named("geometry");
    org.apache.parquet.column.statistics.geospatial.GeospatialStatistics restored =
        ParquetMetadataConverter.fromParquetStatistics(formatStats, type);
    assertThat(restored).isNotNull();
    assertThat(restored.getBoundingBox().getXMin()).isEqualTo(-10);
    assertThat(restored.getBoundingBox().getZMax()).isEqualTo(5);
    assertThat(restored.getGeospatialTypes().getTypes()).containsExactlyInAnyOrder(1001, 5001);

    assertThat(converter.toParquetGeospatialStatistics(null)).isNull();
    assertThat(converter.toParquetGeospatialStatistics(
            new org.apache.parquet.column.statistics.geospatial.GeospatialStatistics()))
        .isNull();
  }

  @Test
  void convertsEdgeInterpolationAlgorithmsInBothDirections() {
    for (org.apache.parquet.column.schema.EdgeInterpolationAlgorithm algorithm
        : org.apache.parquet.column.schema.EdgeInterpolationAlgorithm.values()) {
