  @Test
  void fromParquetMetadataRejectsColumnsFromDifferentFiles() {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("a")
        .required(PrimitiveTypeName.INT32)
        .named("b")
        .named("root");
    List<SchemaElement> schemaElements = new ParquetMetadataConverter().toParquetSchema(schema);

    ColumnMetaData columnA = new ColumnMetaData(
        org.apache.parquet.format.Type.INT32,
        Collections.singletonList(org.apache.parquet.format.Encoding.PLAIN),
        Collections.singletonList("a"),
        CompressionCodec.UNCOMPRESSED,
        1L,
        10L,
        10L,
        100L);
    ColumnMetaData columnB = new ColumnMetaData(
        org.apache.parquet.format.Type.INT32,
        Collections.singletonList(org.apache.parquet.format.Encoding.PLAIN),
        Collections.singletonList("b"),
        CompressionCodec.UNCOMPRESSED,
        1L,
        10L,
        10L,
        200L);
    org.apache.parquet.format.ColumnChunk chunkA =
        new org.apache.parquet.format.ColumnChunk(0L);
    chunkA.setFile_path("file-a.parquet");
    chunkA.setMeta_data(columnA);
    org.apache.parquet.format.ColumnChunk chunkB =
        new org.apache.parquet.format.ColumnChunk(0L);
    chunkB.setFile_path("file-b.parquet");
    chunkB.setMeta_data(columnB);
    RowGroup rowGroup = new RowGroup(Arrays.asList(chunkA, chunkB), 20L, 1L);
    rowGroup.setOrdinal((short) 0);
    FileMetaData metadata = new FileMetaData(1, schemaElements, 1L, Collections.singletonList(rowGroup));
    metadata.setCreated_by(CREATED_BY);

    assertThatThrownBy(() -> new ParquetMetadataConverter().fromParquetMetadata(metadata))
        .isInstanceOf(ParquetDecodingException.class)
        .hasMessage("all column chunks of the same row group must be in the same file for now");
  }
