  private static final String CREATED_BY = "parquet-mr version 1.0.0";

  @Test
  void rejectsNonPositiveStatisticsTruncateLength() {
    assertThatThrownBy(() -> new ParquetMetadataConverter(0))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");
    assertThatThrownBy(() -> new ParquetMetadataConverter(-10))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Truncate length should be greater than 0");
  }

  @Test
  void metadataFiltersExposeTheirOffsetsAndStringRepresentation() {
    ParquetMetadataConverter.RangeMetadataFilter range = (ParquetMetadataConverter.RangeMetadataFilter)
        ParquetMetadataConverter.range(10, 20);
    assertThat(range.contains(10)).isTrue();
    assertThat(range.contains(19)).isTrue();
    assertThat(range.contains(20)).isFalse();
    assertThat(range.contains(9)).isFalse();
    assertThat(range).asString().isEqualTo("range(s:10, e:20)");

    ParquetMetadataConverter.OffsetMetadataFilter offsets = (ParquetMetadataConverter.OffsetMetadataFilter)
        ParquetMetadataConverter.offsets(1, 3, 3);
    assertThat(offsets.contains(3)).isTrue();
    assertThat(offsets.contains(2)).isFalse();
    assertThat(ParquetMetadataConverter.NO_FILTER).asString().isEqualTo("NO_FILTER");
    assertThat(ParquetMetadataConverter.SKIP_ROW_GROUPS).asString().isEqualTo("SKIP_ROW_GROUPS");
  }

  @Test
  void mapsPrimitiveTypesAndRepetitionsInBothDirections() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.BYTE_ARRAY))
        .isEqualTo(PrimitiveTypeName.BINARY);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT64))
        .isEqualTo(PrimitiveTypeName.INT64);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT32))
        .isEqualTo(PrimitiveTypeName.INT32);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.BOOLEAN))
        .isEqualTo(PrimitiveTypeName.BOOLEAN);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.FLOAT))
        .isEqualTo(PrimitiveTypeName.FLOAT);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.DOUBLE))
        .isEqualTo(PrimitiveTypeName.DOUBLE);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.INT96))
        .isEqualTo(PrimitiveTypeName.INT96);
    assertThat(converter.getPrimitive(org.apache.parquet.format.Type.FIXED_LEN_BYTE_ARRAY))
        .isEqualTo(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY);

    assertThat(converter.getType(PrimitiveTypeName.INT64)).isEqualTo(org.apache.parquet.format.Type.INT64);
    assertThat(converter.getType(PrimitiveTypeName.INT32)).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(converter.getType(PrimitiveTypeName.BOOLEAN)).isEqualTo(org.apache.parquet.format.Type.BOOLEAN);
    assertThat(converter.getType(PrimitiveTypeName.BINARY)).isEqualTo(org.apache.parquet.format.Type.BYTE_ARRAY);
    assertThat(converter.getType(PrimitiveTypeName.FLOAT)).isEqualTo(org.apache.parquet.format.Type.FLOAT);
    assertThat(converter.getType(PrimitiveTypeName.DOUBLE)).isEqualTo(org.apache.parquet.format.Type.DOUBLE);
    assertThat(converter.getType(PrimitiveTypeName.INT96)).isEqualTo(org.apache.parquet.format.Type.INT96);
    assertThat(converter.getType(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY))
        .isEqualTo(org.apache.parquet.format.Type.FIXED_LEN_BYTE_ARRAY);

    for (Repetition repetition : Repetition.values()) {
      assertThat(converter.fromParquetRepetition(converter.toParquetRepetition(repetition)))
          .isEqualTo(repetition);
    }
  }

  @Test
  void convertsEncodingsAndDeduplicatesConvertedEncodingSets() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();
    for (Encoding formatEncoding : Encoding.values()) {
      assertThat(converter.getEncoding(formatEncoding).name()).isEqualTo(formatEncoding.name());
      assertThat(converter.getEncoding(converter.getEncoding(formatEncoding))).isEqualTo(formatEncoding);
    }

    Set<Encoding> encodings = new LinkedHashSet<>(Arrays.asList(
        Encoding.PLAIN, Encoding.RLE_DICTIONARY, Encoding.PLAIN_DICTIONARY));
    List<org.apache.parquet.format.Encoding> formatted = converter.toFormatEncodings(encodings);
    assertThat(formatted).hasSize(encodings.size());
    assertThat(formatted).isSorted();
    for (Encoding encoding : encodings) {
      assertThat(formatted).contains(converter.getEncoding(encoding));
    }

    Set<Encoding> first = converter.fromFormatEncodings(formatted);
    Set<Encoding> second = converter.fromFormatEncodings(formatted);
    assertThat(first).containsExactlyInAnyOrderElementsOf(encodings);
    assertThat(second).isSameAs(first);
    assertThatThrownBy(() -> first.add(Encoding.BIT_PACKED))
        .isInstanceOf(UnsupportedOperationException.class);
  }

