  @Test
  void truncatesOrSkipsLargeBinaryStatistics() {
    PrimitiveType type = Types.required(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .named("name");

    Statistics<?> stats = Statistics.createStats(type);
    stats.updateStats(org.apache.parquet.io.api.Binary.fromString("a".repeat(200)));
    stats.updateStats(org.apache.parquet.io.api.Binary.fromString("z".repeat(200)));
    org.apache.parquet.format.Statistics truncated =
        ParquetMetadataConverter.toParquetStatistics(stats, 8);
    assertThat(truncated.isSetMin_value()).isTrue();
    assertThat(truncated.isSetMax_value()).isTrue();
    assertThat(truncated.getMin_value().array().length).isLessThanOrEqualTo(8);
    assertThat(truncated.getMax_value().array().length).isLessThanOrEqualTo(8);
    assertThat(truncated.isSetMin()).isFalse();
    assertThat(truncated.isSetMax()).isFalse();

    Statistics<?> huge = Statistics.createStats(type);
    huge.updateStats(org.apache.parquet.io.api.Binary.fromString("a".repeat(5000)));
    huge.updateStats(org.apache.parquet.io.api.Binary.fromString("z".repeat(5000)));
    huge.setNumNulls(1);
    org.apache.parquet.format.Statistics omitted =
        ParquetMetadataConverter.toParquetStatistics(huge, Integer.MAX_VALUE);
    assertThat(omitted.isSetMin()).isFalse();
    assertThat(omitted.isSetMax()).isFalse();
    assertThat(omitted.isSetMin_value()).isFalse();
    assertThat(omitted.isSetMax_value()).isFalse();
    assertThat(omitted.isSetNull_count()).isFalse();

    Statistics<?> nullOnly = Statistics.createStats(type);
    nullOnly.setNumNulls(9);
    org.apache.parquet.format.Statistics nullOnlyFormat =
        ParquetMetadataConverter.toParquetStatistics(nullOnly);
    assertThat(nullOnlyFormat.getNull_count()).isEqualTo(9);
    assertThat(nullOnlyFormat.hasNonNullValue()).isFalse();
  }

  @Test
  void roundTripsMetadataIncludingColumnsIndexesAndSizeStatistics() throws IOException {
    MessageType schema = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .id(1)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(LogicalTypeAnnotation.stringType())
        .id(2)
        .named("name")
        .named("root");
    PrimitiveType idType = schema.getType("id").asPrimitiveType();
    PrimitiveType nameType = schema.getType("name").asPrimitiveType();

    Statistics<?> idStats = Statistics.createStats(idType);
    idStats.updateStats(7);
    idStats.updateStats(1);
    idStats.setNumNulls(2);

    Statistics<?> nameStats = Statistics.createStats(nameType);
    nameStats.updateStats(org.apache.parquet.io.api.Binary.fromString("aaa"));
    nameStats.updateStats(org.apache.parquet.io.api.Binary.fromString("zzz"));

    EncodingStats idEncodingStats = new EncodingStats.Builder()
        .withV2Pages()
        .addDictEncoding(Encoding.PLAIN_DICTIONARY, 1)
        .addDataEncoding(Encoding.RLE_DICTIONARY, 2)
        .build();
    SizeStatistics nameSizeStats = new SizeStatistics(
        nameType,
        123L,
        Arrays.asList(3L),
        Arrays.asList(2L, 1L));

    ColumnChunkMetaData idColumn = ColumnChunkMetaData.get(
        org.apache.parquet.hadoop.metadata.ColumnPath.get("id"),
        idType,
        CompressionCodecName.SNAPPY,
        idEncodingStats,
        new LinkedHashSet<>(Arrays.asList(Encoding.PLAIN, Encoding.RLE_DICTIONARY)),
        idStats,
        100L,
        50L,
        10L,
        200L,
        250L);
    idColumn.setBloomFilterOffset(900L);
    idColumn.setBloomFilterLength(32);
    idColumn.setColumnIndexReference(new IndexReference(1000L, 20));
    idColumn.setOffsetIndexReference(new IndexReference(1020L, 30));

    ColumnChunkMetaData nameColumn = ColumnChunkMetaData.get(
        org.apache.parquet.hadoop.metadata.ColumnPath.get("name"),
        nameType,
        CompressionCodecName.UNCOMPRESSED,
        new EncodingStats.Builder().addDataEncoding(Encoding.PLAIN, 1).build(),
        new LinkedHashSet<>(Collections.singletonList(Encoding.PLAIN)),
        nameStats,
        400L,
        -1L,
        10L,
        150L,
        170L,
        nameSizeStats);
    nameColumn.setBloomFilterOffset(800L);
    nameColumn.setBloomFilterLength(16);

    BlockMetaData block = new BlockMetaData();
    block.setRowCount(10);
    block.setTotalByteSize(400);
    block.setPath("part-0.parquet");
    block.setOrdinal(0);
    block.addColumn(idColumn);
    block.addColumn(nameColumn);

    Map<String, String> keyValues = new HashMap<>();
    keyValues.put("writer", "test");
    ParquetMetadata metadata = new ParquetMetadata(
