    assertThat(rowGroup.getTotal_byte_size()).isEqualTo(400L);
    assertThat(rowGroup.getFile_offset()).isEqualTo(50L);
    assertThat(rowGroup.getTotal_compressed_size()).isEqualTo(350L);
    assertThat(rowGroup.getOrdinal()).isEqualTo((short) 0);
    assertThat(rowGroup.getColumns()).hasSize(2);

    org.apache.parquet.format.ColumnChunk idChunk = rowGroup.getColumns().get(0);
    assertThat(idChunk.getFile_path()).isEqualTo("part-0.parquet");
    assertThat(idChunk.getColumn_index_offset()).isEqualTo(1000L);
    assertThat(idChunk.getColumn_index_length()).isEqualTo(20);
    assertThat(idChunk.getOffset_index_offset()).isEqualTo(1020L);
    assertThat(idChunk.getOffset_index_length()).isEqualTo(30);
    ColumnMetaData idMeta = idChunk.getMeta_data();
    assertThat(idMeta.getType()).isEqualTo(org.apache.parquet.format.Type.INT32);
    assertThat(idMeta.getPath_in_schema()).containsExactly("id");
    assertThat(idMeta.getCodec()).isEqualTo(CompressionCodec.SNAPPY);
    assertThat(idMeta.getNum_values()).isEqualTo(10L);
    assertThat(idMeta.getTotal_compressed_size()).isEqualTo(200L);
    assertThat(idMeta.getTotal_uncompressed_size()).isEqualTo(250L);
    assertThat(idMeta.getData_page_offset()).isEqualTo(100L);
    assertThat(idMeta.getDictionary_page_offset()).isEqualTo(50L);
    assertThat(idMeta.getBloom_filter_offset()).isEqualTo(900L);
    assertThat(idMeta.getBloom_filter_length()).isEqualTo(32);
    assertThat(idMeta.getEncodings()).contains(
