    assertThat(restoredBlock.getPath()).isEqualTo("part-0.parquet");
    assertThat(restoredBlock.getOrdinal()).isZero();
    assertThat(restoredBlock.getColumns()).hasSize(2);

    ColumnChunkMetaData restoredId = restoredBlock.getColumns().get(0);
    assertThat(restoredId.getPath().toDotString()).isEqualTo("id");
    assertThat(restoredId.getCodec()).isEqualTo(CompressionCodecName.SNAPPY);
    assertThat(restoredId.getFirstDataPageOffset()).isEqualTo(100L);
    assertThat(restoredId.getDictionaryPageOffset()).isEqualTo(50L);
    assertThat(restoredId.getValueCount()).isEqualTo(10L);
    assertThat(restoredId.getTotalSize()).isEqualTo(200L);
    assertThat(restoredId.getTotalUncompressedSize()).isEqualTo(250L);
    assertThat(restoredId.getBloomFilterOffset()).isEqualTo(900L);
    assertThat(restoredId.getBloomFilterLength()).isEqualTo(32);
    assertThat(restoredId.getEncodingStats().usesV2Pages()).isTrue();
    assertThat(restoredId.getStatistics().getMinBytes()).containsExactly(BytesUtils.intToBytes(1));
