    assertThat(restoredId.getOffsetIndexReference().getOffset()).isEqualTo(1020L);
    assertThat(restoredId.getOffsetIndexReference().getLength()).isEqualTo(30);

    ColumnChunkMetaData restoredName = restoredBlock.getColumns().get(1);
    assertThat(restoredName.getSizeStatistics()).isNotNull();
    assertThat(restoredName.getSizeStatistics().getUnencodedByteArrayDataBytes())
        .contains(123L);
    assertThat(restoredName.getSizeStatistics().getRepetitionLevelHistogram())
        .containsExactly(3L);
    assertThat(restoredName.getSizeStatistics().getDefinitionLevelHistogram())
